// ---------------------------------------------------------------------------
// deriveReviewUnitStatus —— 逐句實作 FR-051 五句判定式，不用捷徑邏輯
// ---------------------------------------------------------------------------

function deriveReviewUnitStatus(sim: SimState): ReviewUnitStatus | null {
  // FR-051 判定式第 1 句：標記員未提交 → 不成立審核單位（推導為 null）
  if (!sim.annotatorSubmitted) {
    return null;
  }

  // FR-051 判定式第 2 句：該單位之指派審核員（FR-093）尚未提交 → pending
  if (!sim.reviewerSubmitted) {
    return 'pending';
  }

  const decisionA = sim.outKeyDecisions.outKeyA;
  const decisionB = sim.outKeyDecisions.outKeyB;

  // FR-051 判定式第 3 句：審核員逐項決策皆為 approve → finalized
  const allApproved = decisionA === 'approve' && decisionB === 'approve';
  if (allApproved) {
    return 'finalized';
  }

  // FR-051 判定式第 4 句：任一項決策為 modify 或 bypass → disputed
  const outKeyADisputed = decisionA === 'modify' || decisionA === 'bypass';
  const outKeyBDisputed = decisionB === 'modify' || decisionB === 'bypass';
  const anyDisputed = outKeyADisputed || outKeyBDisputed;

  if (anyDisputed) {
    // FR-051 判定式第 5 句：disputed 單位之所有爭議項皆已解決
    // （仲裁定案 FR-061 或最終例外池收尾 FR-095）→ finalized，否則維持 disputed
    const outKeyAResolved = !outKeyADisputed || sim.disputedResolved.outKeyA;
    const outKeyBResolved = !outKeyBDisputed || sim.disputedResolved.outKeyB;
    const allResolved = outKeyAResolved && outKeyBResolved;
    return allResolved ? 'finalized' : 'disputed';
  }

  // decisions 值域僅 { approve, modify, bypass }：allApproved 為否時 anyDisputed 恆真，
  // 此分支理論上不可達，僅為滿足函式回傳型別的窮舉檢查而保留。
  return 'disputed';
}

// deriveClauseLabel 僅供 UI 顯示「依 FR-051 判定式第 N 句」用，鏡射上方判定式的
// 同一組守衛條件，不影響 deriveReviewUnitStatus 本身的判定結果。
function deriveClauseLabel(sim: SimState): string {
  if (!sim.annotatorSubmitted) {
    return 'FR-051 判定式第 1 句';
  }
  if (!sim.reviewerSubmitted) {
    return 'FR-051 判定式第 2 句';
  }

  const decisionA = sim.outKeyDecisions.outKeyA;
  const decisionB = sim.outKeyDecisions.outKeyB;
  const allApproved = decisionA === 'approve' && decisionB === 'approve';
  if (allApproved) {
    return 'FR-051 判定式第 3 句';
  }

  const outKeyADisputed = decisionA === 'modify' || decisionA === 'bypass';
  const outKeyBDisputed = decisionB === 'modify' || decisionB === 'bypass';
  const outKeyAResolved = !outKeyADisputed || sim.disputedResolved.outKeyA;
  const outKeyBResolved = !outKeyBDisputed || sim.disputedResolved.outKeyB;
  const allResolved = outKeyAResolved && outKeyBResolved;

  return allResolved ? 'FR-051 判定式第 5 句' : 'FR-051 判定式第 4 句（成立爭議）／第 5 句否定分支（維持爭議中）';
}

