// derivePathEdges —— 把 deriveReviewUnitStatus 走過的那條路徑還原成邊的序列，
// 好讓圖上實際亮起「這組決策走的是哪幾條線」。守衛條件與判定式本身不在這裡重算。
function derivePathEdges(sim: SimState): TransitionId[] {
  if (!sim.annotatorSubmitted) {
    return [];
  }
  if (!sim.reviewerSubmitted) {
    return ['null-pending'];
  }

  const decisionA = sim.outKeyDecisions.outKeyA;
  const decisionB = sim.outKeyDecisions.outKeyB;
  if (decisionA === 'approve' && decisionB === 'approve') {
    return ['null-pending', 'pending-finalized'];
  }

  const outKeyADisputed = decisionA === 'modify' || decisionA === 'bypass';
  const outKeyBDisputed = decisionB === 'modify' || decisionB === 'bypass';
  const outKeyAResolved = !outKeyADisputed || sim.disputedResolved.outKeyA;
  const outKeyBResolved = !outKeyBDisputed || sim.disputedResolved.outKeyB;

  return outKeyAResolved && outKeyBResolved
    ? ['null-pending', 'pending-disputed', 'disputed-finalized']
    : ['null-pending', 'pending-disputed', 'disputed-disputed'];
}

// 節點是否落在本次推導走過的路徑上（用於加一圈強調外框，不覆蓋原圖既有配色）。
function nodeOnPath(nodeId: NodeId, edges: TransitionId[]): boolean {
  if (nodeId === 'null') {
    return true;
  }
  return edges.some((id) => id.startsWith(`${nodeId}-`) || id.endsWith(`-${nodeId}`));
}

